<?php
declare(strict_types=1);
namespace App\Services;
use PDO;

final class JudgeDirectoryService{
 public static function ensure(PDO $pdo):void{
  $pdo->exec("CREATE TABLE IF NOT EXISTS bdc_judges(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,judge_code VARCHAR(24) NULL,full_name VARCHAR(160) NOT NULL,display_name VARCHAR(160) NULL,country VARCHAR(100) NULL,country_code CHAR(2) NULL,city VARCHAR(120) NULL,photo_url VARCHAR(500) NULL,instagram VARCHAR(160) NULL,email VARCHAR(190) NULL,phone VARCHAR(80) NULL,whatsapp VARCHAR(80) NULL,preferred_contact ENUM('email','whatsapp','either','none') NOT NULL DEFAULT 'none',dance_styles VARCHAR(120) NULL,judge_role ENUM('regular','chief','both') NOT NULL DEFAULT 'regular',qualified_divisions TEXT NULL,qualified_rounds VARCHAR(160) NULL,languages VARCHAR(500) NULL,biography TEXT NULL,experience TEXT NULL,certification TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',notes TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE INDEX uq_judge_code(judge_code),INDEX idx_judge_name(full_name),INDEX idx_judge_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  foreach(['display_name'=>"VARCHAR(160) NULL AFTER full_name",'city'=>"VARCHAR(120) NULL AFTER country_code",'phone'=>"VARCHAR(80) NULL AFTER email",'whatsapp'=>"VARCHAR(80) NULL AFTER phone",'preferred_contact'=>"ENUM('email','whatsapp','either','none') NOT NULL DEFAULT 'none' AFTER whatsapp",'dance_styles'=>"VARCHAR(120) NULL AFTER preferred_contact",'judge_role'=>"ENUM('regular','chief','both') NOT NULL DEFAULT 'regular' AFTER dance_styles",'qualified_divisions'=>"TEXT NULL AFTER judge_role",'qualified_rounds'=>"VARCHAR(160) NULL AFTER qualified_divisions",'languages'=>"VARCHAR(500) NULL AFTER qualified_rounds",'biography'=>"TEXT NULL AFTER languages",'experience'=>"TEXT NULL AFTER biography",'certification'=>"TEXT NULL AFTER experience"] as $column=>$definition){try{$pdo->exec("ALTER TABLE bdc_judges ADD COLUMN {$column} {$definition}");}catch(\Throwable){}}
  foreach(['bdc_scoring_judges','bdc_test_scoring_judges'] as $table){try{$pdo->exec("ALTER TABLE {$table} ADD COLUMN judge_id BIGINT UNSIGNED NULL AFTER id");}catch(\Throwable){}try{$pdo->exec("ALTER TABLE {$table} ADD INDEX idx_judge_directory(judge_id)");}catch(\Throwable){}}
 }
 public static function search(PDO $pdo,string $term,int $limit=15):array{self::ensure($pdo);$term=trim($term);if(mb_strlen($term)<1)return [];$contains='%'.$term.'%';$prefix=$term.'%';$s=$pdo->prepare("SELECT id,judge_code,full_name,display_name,country,country_code,photo_url,instagram,email,phone,whatsapp,preferred_contact,judge_role,dance_styles FROM bdc_judges WHERE status='active' AND (LOWER(full_name) LIKE LOWER(:full_contains) OR LOWER(COALESCE(display_name,'')) LIKE LOWER(:display_contains) OR LOWER(COALESCE(judge_code,'')) LIKE LOWER(:code_prefix) OR LOWER(COALESCE(instagram,'')) LIKE LOWER(:instagram_contains)) ORDER BY CASE WHEN LOWER(full_name) LIKE LOWER(:full_prefix) THEN 0 WHEN LOWER(COALESCE(display_name,'')) LIKE LOWER(:display_prefix) THEN 1 ELSE 2 END,LOWER(COALESCE(NULLIF(display_name,''),full_name)),id LIMIT ".max(1,min(100,$limit)));$s->execute(['full_contains'=>$contains,'display_contains'=>$contains,'code_prefix'=>$prefix,'instagram_contains'=>$contains,'full_prefix'=>$prefix,'display_prefix'=>$prefix]);return $s->fetchAll();}
 public static function findOrCreate(PDO $pdo,string $name,array $meta=[]):array{self::ensure($pdo);$name=trim($name);if($name==='')throw new \RuntimeException('Judge name is required.');$s=$pdo->prepare("SELECT * FROM bdc_judges WHERE LOWER(full_name)=LOWER(:n) ORDER BY status='active' DESC,id LIMIT 1");$s->execute(['n'=>$name]);if($j=$s->fetch())return $j;return self::create($pdo,array_merge($meta,['full_name'=>$name]));}
 public static function mergeProfile(PDO $pdo,int $id,array $data):array{$preferred=in_array(($data['preferred_contact']??''),['email','whatsapp','either','none'],true)?$data['preferred_contact']:'none';$role=in_array(($data['judge_role']??''),['regular','chief','both'],true)?$data['judge_role']:'regular';$pdo->prepare("UPDATE bdc_judges SET display_name=COALESCE(NULLIF(:display,''),display_name),country=COALESCE(NULLIF(:country,''),country),country_code=COALESCE(NULLIF(:code,''),country_code),city=COALESCE(NULLIF(:city,''),city),photo_url=COALESCE(NULLIF(:photo,''),photo_url),instagram=COALESCE(NULLIF(:instagram,''),instagram),email=COALESCE(NULLIF(:email,''),email),phone=COALESCE(NULLIF(:phone,''),phone),whatsapp=COALESCE(NULLIF(:whatsapp,''),whatsapp),preferred_contact=IF(:preferred='none',preferred_contact,:preferred2),dance_styles=COALESCE(NULLIF(:styles,''),dance_styles),judge_role=IF(:role='regular',judge_role,:role2),qualified_divisions=COALESCE(NULLIF(:divisions,''),qualified_divisions),qualified_rounds=COALESCE(NULLIF(:rounds,''),qualified_rounds),languages=COALESCE(NULLIF(:languages,''),languages),biography=COALESCE(NULLIF(:bio,''),biography),experience=COALESCE(NULLIF(:experience,''),experience),certification=COALESCE(NULLIF(:certification,''),certification) WHERE id=:id")->execute(['display'=>(string)($data['display_name']??''),'country'=>(string)($data['country']??''),'code'=>(string)(CountryFlagService::code($data['country']??null)??''),'city'=>(string)($data['city']??''),'photo'=>(string)($data['photo_url']??''),'instagram'=>ltrim(trim((string)($data['instagram']??'')),'@'),'email'=>(string)($data['email']??''),'phone'=>(string)($data['phone']??''),'whatsapp'=>(string)($data['whatsapp']??''),'preferred'=>$preferred,'preferred2'=>$preferred,'styles'=>(string)($data['dance_styles']??''),'role'=>$role,'role2'=>$role,'divisions'=>(string)($data['qualified_divisions']??''),'rounds'=>(string)($data['qualified_rounds']??''),'languages'=>(string)($data['languages']??''),'bio'=>(string)($data['biography']??''),'experience'=>(string)($data['experience']??''),'certification'=>(string)($data['certification']??''),'id'=>$id]);$s=$pdo->prepare('SELECT * FROM bdc_judges WHERE id=:id');$s->execute(['id'=>$id]);return $s->fetch();}
 public static function create(PDO $pdo,array $data):array{self::ensure($pdo);$name=trim((string)($data['full_name']??''));if($name==='')throw new \RuntimeException('Judge name is required.');$email=strtolower(trim((string)($data['email']??'')));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new \RuntimeException('Enter a valid email or leave it blank.');$preferred=in_array(($data['preferred_contact']??''),['email','whatsapp','either','none'],true)?$data['preferred_contact']:'none';$role=in_array(($data['judge_role']??''),['regular','chief','both'],true)?$data['judge_role']:'regular';$pdo->prepare("INSERT INTO bdc_judges(full_name,display_name,country,country_code,city,photo_url,instagram,email,phone,whatsapp,preferred_contact,dance_styles,judge_role,qualified_divisions,qualified_rounds,languages,biography,experience,certification,status,notes) VALUES(:name,:display,:country,:code,:city,:photo,:ig,:email,:phone,:whatsapp,:preferred,:styles,:role,:divisions,:rounds,:languages,:bio,:experience,:certification,:status,:notes)")->execute(['name'=>$name,'display'=>self::nullable($data['display_name']??null),'country'=>self::nullable($data['country']??null),'code'=>CountryFlagService::code($data['country']??null),'city'=>self::nullable($data['city']??null),'photo'=>self::nullable($data['photo_url']??null),'ig'=>self::nullable(ltrim(trim((string)($data['instagram']??'')),'@')),'email'=>$email?:null,'phone'=>self::nullable($data['phone']??null),'whatsapp'=>self::nullable($data['whatsapp']??null),'preferred'=>$preferred,'styles'=>self::nullable($data['dance_styles']??null),'role'=>$role,'divisions'=>self::nullable($data['qualified_divisions']??null),'rounds'=>self::nullable($data['qualified_rounds']??null),'languages'=>self::nullable($data['languages']??null),'bio'=>self::nullable($data['biography']??null),'experience'=>self::nullable($data['experience']??null),'certification'=>self::nullable($data['certification']??null),'status'=>in_array(($data['status']??''),['active','inactive'],true)?$data['status']:'active','notes'=>self::nullable($data['notes']??null)]);$id=(int)$pdo->lastInsertId();$code='JDG-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE bdc_judges SET judge_code=:code WHERE id=:id')->execute(['code'=>$code,'id'=>$id]);$s=$pdo->prepare('SELECT * FROM bdc_judges WHERE id=:id');$s->execute(['id'=>$id]);return $s->fetch();}
 public static function backfillAssignments(PDO $pdo):void{self::ensure($pdo);foreach(['bdc_scoring_judges','bdc_test_scoring_judges'] as $table){try{$rows=$pdo->query("SELECT id,judge_name FROM {$table} WHERE judge_id IS NULL AND judge_name<>''")->fetchAll();foreach($rows as $r){$j=self::findOrCreate($pdo,(string)$r['judge_name']);$pdo->prepare("UPDATE {$table} SET judge_id=:j WHERE id=:id")->execute(['j'=>$j['id'],'id'=>$r['id']]);}}catch(\Throwable){}}}
 public static function ensureProfileRequests(PDO $pdo):void{$pdo->exec("CREATE TABLE IF NOT EXISTS bdc_judge_profile_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,display_name VARCHAR(160) NULL,country VARCHAR(100) NULL,city VARCHAR(120) NULL,photo_url VARCHAR(500) NULL,instagram VARCHAR(160) NULL,email VARCHAR(190) NULL,phone VARCHAR(80) NULL,whatsapp VARCHAR(80) NULL,preferred_contact ENUM('email','whatsapp','either','none') NOT NULL DEFAULT 'none',dance_styles VARCHAR(120) NULL,judge_role ENUM('regular','chief','both') NOT NULL DEFAULT 'regular',qualified_divisions TEXT NULL,qualified_rounds VARCHAR(160) NULL,languages VARCHAR(500) NULL,biography TEXT NULL,experience TEXT NULL,certification TEXT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',admin_notes TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_judge_profile_request_status(status),INDEX idx_judge_profile_request_name(full_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
 private static function nullable(mixed $value):?string{$value=trim((string)$value);return $value===''?null:$value;}
}
